"""Private dev-only operator guard. Does not alter server/auth implementation."""
import hashlib,json,os,signal,subprocess,time,traceback
from pathlib import Path
from uuid import uuid4
from remoterf_device_core.integrations.supervision import CgroupSupervisor
import importlib.util
BASE=Path('/tmp/remoterf-phase1c-e2e-20261110')
STATE=BASE/'server-guardian-v4';STATE.mkdir(mode=0o700)
CONFIG=BASE/'service/config/remoterf'
BOOKING='52ae81ca-fd98-4e4c-8819-38cffa86247b:1029'
manager=Path('/sys/fs/cgroup')/Path('/proc/self/cgroup').read_text().strip().split('::',1)[1].lstrip('/')
assert manager.name=='manager' and manager.parent.name=='remoterf-phase1c-e2e-server-20261110.service'
root=manager.parent;(root/'cgroup.subtree_control').write_text('+pids +memory')
apps=root/'apps';apps.mkdir();(apps/'cgroup.subtree_control').write_text('+pids +memory')
apps_fd=os.open(apps,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
apps_identity=[os.fstat(apps_fd).st_dev,os.fstat(apps_fd).st_ino]
spec=importlib.util.spec_from_file_location('guardian_helper',BASE/'usrp_handoff.py');helper=importlib.util.module_from_spec(spec);spec.loader.exec_module(helper)
spec=importlib.util.spec_from_file_location('guardian_pidfd',BASE/'usrp_e2e_descendants.py');pidfd=importlib.util.module_from_spec(spec);spec.loader.exec_module(pidfd)
assert pidfd.pidfd_supported(),'Linux pidfd support required'
supervisor=CgroupSupervisor(root,STATE/'processes',max_scopes=2,max_processes=1,max_pids=256,memory_bytes=1024**3)
scope=None;process=None;process_id=None;server_pidfd=None;radio_lock=None;hardware=False;sequence=0
evidence={'started_at':time.time(),'root':str(root),'identity':[root.stat().st_dev,root.stat().st_ino],'apps':str(apps),'apps_identity':[apps.stat().st_dev,apps.stat().st_ino],'guardian_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'events':[]}
def write(path,value):
 temp=path.with_suffix('.new');temp.write_text(json.dumps(value,indent=2)+'\n');os.chmod(temp,0o600);temp.replace(path)
def save():write(STATE/'evidence.json',evidence)
def authority():
 result=subprocess.run([str(BASE/'authority'),'--reservation-id',BOOKING,'--device-id','40','--serial','32C78EE'],capture_output=True,timeout=2)
 assert result.returncode==0 and len(result.stdout)<4096,'outer authority query failed'
 v=json.loads(result.stdout);assert v['active'] is True and (v['reservation_id'],v['device_id'],v['serial'],v['expires_at'])==(BOOKING,40,'32C78EE',1794344400),'outer booking inactive'
 assert time.time()<1794344400-120,'outer booking cleanup margin reached'
 return v
def usb_free():
 nodes=[]
 for p in Path('/sys/bus/usb/devices').glob('*/serial'):
  try:
   if p.read_text().strip()=='32C78EE':nodes.append(p.parent)
  except OSError:pass
 assert len(nodes)==1,'USB serial not unique'
 d=nodes[0];node=Path('/dev/bus/usb')/('%03d'%int((d/'busnum').read_text()))/('%03d'%int((d/'devnum').read_text()))
 result=subprocess.run(['fuser',str(node)],capture_output=True,timeout=2)
 assert result.returncode==1 and not result.stdout.strip() and not result.stderr.strip(),'USB owner remains'
 return {'node':str(node),'owners':0}
def clean_apps():
 assert [apps.stat().st_dev,apps.stat().st_ino]==evidence['apps_identity'],'apps root identity changed'
 state=CONFIG/'db/integrations'
 hp=state/'ownership/ownership.json'; pp=state/'processes/scopes.json'
 if hp.exists():assert json.loads(hp.read_text())=={},'hardware owners remain'
 if pp.exists():
  data=json.loads(pp.read_text());assert data['scopes']=={},'application scopes remain'
  assert data['root']==evidence['apps_identity'],'process journal root differs'
 assert not list(apps.glob('rrf-*')),'unrecorded owned application cgroup'
 assert not (apps/'cgroup.procs').read_text().strip(),'apps root has processes'
 assert dict(line.split() for line in (apps/'cgroup.events').read_text().splitlines())['populated']=='0','application descendants remain'
 return {'hardware_records':0,'process_records':0,'owned_cgroups':0,'root_identity_verified':True}
def emergency_apps():
 assert [os.fstat(apps_fd).st_dev,os.fstat(apps_fd).st_ino]==apps_identity==[apps.stat().st_dev,apps.stat().st_ino],'emergency apps identity differs'
 fd=os.open('cgroup.kill',os.O_WRONLY|os.O_NOFOLLOW,dir_fd=apps_fd)
 try:os.write(fd,b'1')
 finally:os.close(fd)
 until=time.monotonic()+10
 while True:
  assert [apps.stat().st_dev,apps.stat().st_ino]==apps_identity
  populated=dict(line.split() for line in (apps/'cgroup.events').read_text().splitlines())['populated']
  if populated=='0':break
  assert time.monotonic()<until,'emergency application scope did not empty'
  time.sleep(.05)
 return {'identity_verified':True,'populated':0,'journals_retained':True,'normal_cleanup_claimed':False,'at':time.time()}
def stop(reason):
 global scope,process,process_id,server_pidfd,radio_lock,hardware
 event={'action':'stop','reason':reason,'started_at':time.time()};evidence['events'].append(event);save()
 if scope is not None and process is None:
  event['partial_launch_cleanup']=scope.stop(timeout=5)
  assert event['partial_launch_cleanup'],'partial launch scope remains'
  scope.close();scope=None
 if process is not None:
  if process.poll() is None:
   if server_pidfd is None:event['uncaptured_server_cleanup']=scope.stop(timeout=5)
   else:pidfd.pidfd_send_signal(server_pidfd,signal.SIGTERM)
  until=time.monotonic()+30
  while process.poll() is None and time.monotonic()<until:time.sleep(.1)
  event['returncode']=process.poll()
  if process.poll() is None:
   event['forced_server_scope_cleanup']=scope.stop(timeout=5)
  deadline=time.monotonic()+10
  while not scope.resources_released() and time.monotonic()<deadline:time.sleep(.1)
  if not scope.resources_released():event['forced_server_descendant_cleanup']=scope.stop(timeout=5)
  for stream in ('stdout','stderr'):(STATE/('server-%02d-%s.log'%(sequence,stream))).write_bytes(scope.log_tail(process_id,stream))
  event['server_resources_released']=scope.resources_released()
  assert event['server_resources_released'],'server descendant remains'
  scope.close();scope=process=process_id=None
  if server_pidfd is not None:os.close(server_pidfd);server_pidfd=None
 event['applications']=clean_apps()
 if hardware:event['usb']=usb_free()
 if radio_lock is not None:os.close(radio_lock);radio_lock=None
 hardware=False;event['finished_at']=time.time();save()
def start():
 global scope,process,process_id,server_pidfd,radio_lock,hardware,sequence
 import yaml
 assert scope is None and process is None,'server already active'
 clean_apps()
 devices=yaml.safe_load((CONFIG/'devices.yml').read_text())['devices']
 hardware=bool(devices)
 if hardware:
  assert len(devices)==1 and devices[0]['device_id']==40 and devices[0]['device_type']=='usrp' and devices[0]['init']=={'profile':'usrp2901','type':'b200','serial':'32C78EE'},'unexpected inventory'
  authority();assert time.time()<1794344400-300,'insufficient outer booking time'
  radio_lock=helper.acquire_radio_lock('32C78EE');usb_free()
 sequence+=1;scope=supervisor.create('server-'+uuid4().hex)
 env={'HOME':str(Path.home()),'PATH':'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','LANG':'C.UTF-8','LC_ALL':'C.UTF-8','XDG_RUNTIME_DIR':os.environ['XDG_RUNTIME_DIR']}
 process_id=scope.launch([str(BASE/'private-server'),'--serve','--headless'],env=env,cwd=BASE,timeout=30)
 process=scope._processes[process_id]['popen']
 with scope._lock:
  scope._verify_identity();assert process.poll() is None,'server exited before signal identity capture'
  server_pidfd=pidfd.pidfd_open(process.pid)
  cgroup=root/supervisor.describe()['owners'][scope.owner_id]['name']
  assert str(process.pid) in (cgroup/'cgroup.procs').read_text().split(),'server outside owned scope'
  if process.poll() is not None:
   os.close(server_pidfd);server_pidfd=None
   raise RuntimeError('server exited during pidfd capture')
 evidence['events'].append({'action':'start','at':time.time(),'hardware_inventory':hardware,'sequence':sequence,'owner':scope.owner_id,'server_scope':supervisor.describe()['owners'][scope.owner_id]});save()
write(STATE/'ready.json',{'root':str(root),'identity':evidence['identity'],'apps':str(apps),'apps_identity':evidence['apps_identity']})
failed=False;last_authority=0
while True:
 try:
  if process is not None:
   assert process.poll() is None,'normal canary server exited unexpectedly'
   if hardware and time.monotonic()-last_authority>=1:authority();last_authority=time.monotonic()
  for command in sorted(STATE.glob('command-*.json')):
   if command.name.endswith('.result.json'):continue
   value=json.loads(command.read_text());done=command.with_name(command.stem+'.result.json')
   if done.exists():continue
   assert set(value)=={'action'} and value['action'] in {'start','stop','release'},'invalid guardian command'
   if failed and value['action']=='start':raise RuntimeError('guardian failure requires operator review')
   if value['action']=='start':start()
   elif value['action']=='stop':stop('operator')
   else:
    assert process is None and scope is None and not hardware
    clean_apps();assert supervisor.describe()['owners']=={};supervisor.close();os.close(apps_fd);apps.rmdir()
    write(done,{'passed':True,'at':time.time()});evidence['released_at']=time.time();save();raise SystemExit(0)
   write(done,{'passed':True,'at':time.time()})
  time.sleep(.1)
 except Exception as exc:
  failed=True;evidence['failure']={'type':type(exc).__name__,'message':str(exc),'at':time.time(),'trace':[{'file':Path(f.filename).name,'line':f.lineno} for f in traceback.extract_tb(exc.__traceback__)[-6:]]};save()
  try:stop('guardian_failure')
  except Exception as cleanup:evidence['cleanup_failure']={'type':type(cleanup).__name__,'message':str(cleanup)};save()
  try:evidence['emergency_app_cleanup']=emergency_apps();evidence['emergency_usb']=usb_free();save()
  except Exception as cleanup:evidence['emergency_cleanup_failure']={'type':type(cleanup).__name__,'message':str(cleanup)};save()
  while not (STATE/'failure-reviewed').exists():time.sleep(.25)
  raise
